                _arguments = ast.literal_eval(arguments)
        except Exception as e:
            log_error(f"Unable to decode function arguments:\n{arguments}\nError: {e}")
            function_call.error = (
                f"Error while decoding function arguments: {e}\n\n"
                f"Please make sure we can json.loads() the arguments and retry."
            )
            return function_call

        if not isinstance(_arguments, dict):
            log_error(f"Function arguments are not a valid JSON object: {arguments}")
            function_call.error = "Function arguments are not a valid JSON object.\n\n Please fix and retry."
            return function_call

        try:
            clean_arguments: Dict[str, Any] = {}
            for k, v in _arguments.items():
                if isinstance(v, str):
                    _v = v.strip().lower()
                    if _v in ("none", "null"):
                        clean_arguments[k] = None
                    elif _v == "true":
                        clean_arguments[k] = True
                    elif _v == "false":
                        clean_arguments[k] = False
                    else:
                        clean_arguments[k] = v.strip()
                else:
                    clean_arguments[k] = v

            function_call.arguments = clean_arguments
        except Exception as e:
            log_error(f"Unable to parsing function arguments:\n{arguments}\nError: {e}")
            function_call.error = f"Error while parsing function arguments: {e}\n\n Please fix and retry."
            return function_call
    return function_call

def with_history_disabled(func):
    """Decorator to temporarily disable history saving for the prompt session buffer."""

    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        try:
            orig_buf_append = self.prompt_session.default_buffer.append_to_history
            self.prompt_session.default_buffer.append_to_history = (
                lambda: None
            )  # Replace with no-op
        except AttributeError:
            pass

        try:
            return func(self, *args, **kwargs)
        except Exception:
            raise
        finally:
            if orig_buf_append:
                self.prompt_session.default_buffer.append_to_history = orig_buf_append

    return wrapper

def get_input(
    self,
    root,
    rel_fnames,
    addable_rel_fnames,
    commands,
    abs_read_only_fnames=None,
    edit_format=None,
):
    self.rule()

    # Ring the bell if needed
    self.ring_bell()

    rel_fnames = list(rel_fnames)
    show = ""
    if rel_fnames:
        rel_read_only_fnames = [
            get_rel_fname(fname, root) for fname in (abs_read_only_fnames or [])
        ]
        show = self.format_files_for_input(rel_fnames, rel_read_only_fnames)

    prompt_prefix = ""
    if edit_format:
        prompt_prefix += edit_format
    if self.multiline_mode:
        prompt_prefix += (" " if edit_format else "") + "multi"
    prompt_prefix += "> "

    show += prompt_prefix
    self.prompt_prefix = prompt_prefix

    inp = ""
    multiline_input = False

    style = self._get_style()

    completer_instance = ThreadedCompleter(
        AutoCompleter(
            root,
            rel_fnames,
            addable_rel_fnames,
            commands,
            self.encoding,
            abs_read_only_fnames=abs_read_only_fnames,
        )
    )

    def suspend_to_bg(event):
        """Suspend currently running application."""
        event.app.suspend_to_background()

    kb = KeyBindings()

    @kb.add(Keys.ControlZ, filter=Condition(lambda: hasattr(signal, "SIGTSTP")))
    def _(event):
        "Suspend to background with ctrl-z"
        suspend_to_bg(event)

    @kb.add("c-space")
    def _(event):
        "Ignore Ctrl when pressing space bar"
        event.current_buffer.insert_text(" ")

    @kb.add("c-up")
    def _(event):
        "Navigate backward through history"
        event.current_buffer.history_backward()

    @kb.add("c-down")
    def _(event):
        "Navigate forward through history"
        event.current_buffer.history_forward()

    @kb.add("c-x", "c-e")
    def _(event):
        "Edit current input in external editor (like Bash)"
        buffer = event.current_buffer
        current_text = buffer.text

        # Open the editor with the current text
        edited_text = pipe_editor(input_data=current_text, suffix="md")

        # Replace the buffer with the edited text, strip any trailing newlines
        buffer.text = edited_text.rstrip("\n")

        # Move cursor to the end of the text
        buffer.cursor_position = len(buffer.text)

    @kb.add("enter", eager=True, filter=~is_searching)
    def _(event):
        "Handle Enter key press"
        if self.multiline_mode and not (
            self.editingmode == EditingMode.VI
            and event.app.vi_state.input_mode == InputMode.NAVIGATION
        ):
            # In multiline mode and if not in vi-mode or vi navigation/normal mode,
            # Enter adds a newline
            event.current_buffer.insert_text("\n")
        else:
            # In normal mode, Enter submits
            event.current_buffer.validate_and_handle()

    @kb.add("escape", "enter", eager=True, filter=~is_searching)  # This is Alt+Enter
    def _(event):
        "Handle Alt+Enter key press"
        if self.multiline_mode:
            # In multiline mode, Alt+Enter submits
            event.current_buffer.validate_and_handle()
        else:
            # In normal mode, Alt+Enter adds a newline
            event.current_buffer.insert_text("\n")

    while True:
        if multiline_input:
            show = self.prompt_prefix

        try:
            if self.prompt_session:
                # Use placeholder if set, then clear it
                default = self.placeholder or ""
                self.placeholder = None

                self.interrupted = False
                if not multiline_input:
                    if self.file_watcher:
                        self.file_watcher.start()
                    if self.clipboard_watcher:
                        self.clipboard_watcher.start()

                def get_continuation(width, line_number, is_soft_wrap):
                    return self.prompt_prefix

                line = self.prompt_session.prompt(
                    show,
                    default=default,
                    completer=completer_instance,
                    reserve_space_for_menu=4,
                    complete_style=CompleteStyle.MULTI_COLUMN,
                    style=style,
                    key_bindings=kb,
                    complete_while_typing=True,
                    prompt_continuation=get_continuation,
                )
            else:
                line = input(show)

            # Check if we were interrupted by a file change
            if self.interrupted:
                line = line or ""
                if self.file_watcher:
                    cmd = self.file_watcher.process_changes()
                    return cmd

        except EOFError:
            raise
        except Exception as err:
            import traceback

            self.tool_error(str(err))
            self.tool_error(traceback.format_exc())
            return ""
        except UnicodeEncodeError as err:
            self.tool_error(str(err))
            return ""
        finally:
            if self.file_watcher:
                self.file_watcher.stop()
            if self.clipboard_watcher:
                self.clipboard_watcher.stop()

        if line.strip("\r\n") and not multiline_input:
            stripped = line.strip("\r\n")
            if stripped == "{":
                multiline_input = True
                multiline_tag = None
                inp += ""
            elif stripped[0] == "{":
                # Extract tag if it exists (only alphanumeric chars)
                tag = "".join(c for c in stripped[1:] if c.isalnum())
                if stripped == "{" + tag:
                    multiline_input = True
                    multiline_tag = tag
                    inp += ""
                else:
                    inp = line
                    break
            else:
                inp = line
                break
            continue
        elif multiline_input and line.strip():
            if multiline_tag:
                # Check if line is exactly "tag}"
                if line.strip("\r\n") == f"{multiline_tag}}}":
                    break
                else:
                    inp += line + "\n"
            # Check if line is exactly "}"
            elif line.strip("\r\n") == "}":
                break
            else:
                inp += line + "\n"
        elif multiline_input:
            inp += line + "\n"
        else:
            inp = line
            break

    print()
    self.user_input(inp)
    return inp

