def check(self, element_name: str, prop_name: str):
    if not isinstance(prop_name, str) or not prop_name or not prop_name.isidentifier():
        _warn(f"Property name '{prop_name}' is invalid for element '{element_name}'.")
    if not isinstance(self.property_type, PropertyType) and not (
        isclass(self.property_type) and issubclass(self.property_type, _TaipyBase)
    ):
        _warn(f"Property type '{self.property_type}' is invalid for element property '{element_name}.{prop_name}'.")

def _get_tuple(self, name: str) -> tuple:
    return (
        (name, self.property_type, self.default_value)
        if self.with_update is None
        else (name, self.property_type, self.default_value, self.with_update)
    )

def last_edit_date(self) -> Optional[datetime]:
    """The date and time of the last modification."""
    if hasattr(self, "_get_last_modified_datetime"):
        last_modified_datetime = self._get_last_modified_datetime()
    else:
        last_modified_datetime = None

    if last_modified_datetime and last_modified_datetime > self._last_edit_date:  # type: ignore
        return last_modified_datetime
    else:
        return self._last_edit_date

def is_up_to_date(self) -> bool:
    """Indicate if this data node is up-to-date.

    False if a preceding data node has been updated before the selected data node
    or the selected data is invalid.<br/>
    True otherwise.
    """
    if self.is_valid:
        from ..scenario.scenario import Scenario
        from ..taipy import get_parents

        parent_scenarios: Set[Scenario] = get_parents(self)["scenario"]  # type: ignore
        for parent_scenario in parent_scenarios:
            for ancestor_node in nx.ancestors(parent_scenario._build_dag(), self):
                if (
                    isinstance(ancestor_node, DataNode)
                    and ancestor_node.last_edit_date
                    and ancestor_node.last_edit_date > cast(datetime, self.last_edit_date)
                ):
                    return False
        return True
    return False

