def __send_ws(self, payload: dict, allow_grouping=True, send_back_only=False) -> None:
    grouping_message = self.__get_message_grouping() if allow_grouping else None
    if grouping_message is None:
        try:
            self._server._ws.emit(
                "message",
                payload,
                to=t.cast(str, self.__get_ws_receiver(send_back_only)),
            )
            time.sleep(0.001)
        except Exception as e:  # pragma: no cover
            _warn(f"Exception raised in WebSocket communication in '{self.__frame.f_code.co_name}'", e)
    else:
        grouping_message.append(payload)

def __send_ack(self, ack_id: t.Optional[str]) -> None:
    if ack_id:
        try:
            self._server._ws.emit(
                "message",
                {"type": _WsType.ACKNOWLEDGEMENT.value, "id": ack_id},
                to=t.cast(str, self.__get_ws_receiver(True)),
            )
            time.sleep(0.001)
        except Exception as e:  # pragma: no cover
            _warn(f"Exception raised in WebSocket communication (send ack) in '{self.__frame.f_code.co_name}'", e)

class TestAwsCliVenv:
    def _normalize_dependency_entry(self, dep: str) -> str:
        dep = re.split("[<=>]", dep)[0]
        dep = dep.rstrip("<=>")
        dep = dep.lower()
        dep = dep.replace("-", "_")
        dep = dep.replace(".", "_")
        return dep

    def _normalize_dist_info_name(self, name: str) -> str:
        name = name.split("-")[0]
        name = name.lower()
        name = name.replace(".", "_")
        return name

    def _get_install_requires(self):
        with cd(ROOT_DIR):
            requires = flit_core.buildapi.get_requires_for_build_wheel()
        # Generation of the auto-complete index requires importing from the
        # awscli package and iterating over the commands from the clidriver. In
        # order to be able to do this, it requires all of the CLI's runtime
        # dependencies to be present to avoid import errors.
        dependency_block_re = re.compile(
            r"dependencies = \[([\s\S]+?)\]", re.MULTILINE
        )
        extract_dependencies_re = re.compile(r'"(.+)"')
        with open(ROOT_DIR / "pyproject.toml") as f:
            data = f.read()
        raw_dependencies = dependency_block_re.findall(data)[0]
        dependencies = extract_dependencies_re.findall(raw_dependencies)
        return dependencies + requires

    def _python_version(self) -> str:
        info = sys.version_info
        return f"python{info[0]}.{info[1]}"

    def _site_packages_dir(self, venv_path: pathlib.PurePath) -> str:
        site_path = [
            path
            for path in json.loads(
                subprocess.check_output(
                    [
                        venv_path / BIN_DIRNAME / PYTHON_EXE_NAME,
                        "-c",
                        "import site, json; print(json.dumps(site.getsitepackages()))",
                    ]
                )
                .decode()
                .strip()
            )
            if "site-packages" in path
        ][0]
        return site_path

